'use strict';

let base = {};
try { base = $('Set | Scheduler Constants | StateScheduler').first().json || {}; } catch {}
const clean = value => String(value ?? '').normalize('NFKC').trim();
const rows = $input.all().flatMap(item => {
  const value = item?.json?.body ?? item?.json ?? {};
  return Array.isArray(value) ? value : (Array.isArray(value?.data) ? value.data : [value]);
});

return rows.filter(row => row && clean(row.step_id ?? row.stepId) &&
  clean(row.lease_token ?? row.leaseToken) &&
  Number.isSafeInteger(Number(row.step_version ?? row.stepVersion)) &&
  ['ask', 'answer'].includes(clean(row.lease_phase ?? row.leasePhase)) &&
  clean(row.principal_id ?? row.principalId) && clean(row.session_id ?? row.sessionId)
).map(row => ({ json: {
  ...base,
  ...row,
  stateClarificationStep: row,
  stateClarificationStepPhase: clean(row.lease_phase ?? row.leasePhase),
  stateClarificationStepContractVersion: clean(row.clarification_context?.contractVersion) === 'chelsea_clarification_context_v1'
    ? 'chelsea_state_clarification_step_claim_v3'
    : 'chelsea_state_clarification_step_claim_invalid'
} }));

'use strict';

const claim = $('Code | Normalize Clarification Ask Claims | ClarificationAsk').item.json || {};
const incoming = $input.first()?.json || {};
const body = incoming.body && typeof incoming.body === 'object' ? incoming.body : incoming;
const clean = value => String(value ?? '').normalize('NFKC').trim();
const principalId = clean(claim.principal_id ?? claim.principalId);
const contextValid = body && typeof body === 'object' && !Array.isArray(body) &&
  body.contractVersion === 'chelsea_state_summary_v1' &&
  clean(body.principalId ?? body.principal_id) === principalId;
const delivery = contextValid && body.deliveryContext && typeof body.deliveryContext === 'object'
  ? body.deliveryContext : {};
const preferredName = clean(delivery.displayName ?? delivery.currentUsername).replace(/[,;:]+$/u, '').trim();
const chatId = clean(delivery.telegramChatId ?? delivery.deliveryAddress);
const questionText = clean(claim.question_text ?? claim.questionText);
const questionKey = clean(claim.question_key ?? claim.questionKey);
const replyToken = clean(claim.reply_token ?? claim.replyToken);
const clarificationContext = claim.clarification_context && typeof claim.clarification_context === 'object'
  ? claim.clarification_context
  : (claim.clarificationContext && typeof claim.clarificationContext === 'object' ? claim.clarificationContext : {});
const options = Array.isArray(claim.callback_options ?? claim.callbackOptions)
  ? (claim.callback_options ?? claim.callbackOptions) : [];
const normalizedOptions = options.map(option => ({
  optionCode: clean(option?.optionCode ?? option?.option_code),
  label: clean(option?.label),
  token: clean(option?.token),
  callbackData: clean(option?.callbackData ?? option?.callback_data)
})).filter(option => option.optionCode && option.label && /^[0-9a-f]{16}$/.test(option.token) &&
  option.callbackData === `csq:${questionKey}:${option.token}`);
const skipOptions = normalizedOptions.filter(option => option.optionCode === 'skip_analysis');
const regularOptions = normalizedOptions.filter(option => option.optionCode !== 'skip_analysis');
const optionsUnique = new Set(normalizedOptions.map(option => option.optionCode)).size === normalizedOptions.length &&
  new Set(normalizedOptions.map(option => option.token)).size === normalizedOptions.length &&
  new Set(normalizedOptions.map(option => option.callbackData)).size === normalizedOptions.length;
const rows = [];
const withEmoji = label => {
  if (/^[\p{Extended_Pictographic}\u2600-\u27BF]/u.test(label)) return label;
  const value = label.toLocaleLowerCase('ru-RU');
  if (value === 'стало лучше') return `📈 ${label}`;
  if (value === 'без явного эффекта') return `😐 ${label}`;
  if (value === 'стало хуже') return `📉 ${label}`;
  return `🔹 ${label}`;
};
for (let index = 0; index < regularOptions.length; index += 2) {
  rows.push({ row: { buttons: regularOptions.slice(index,index + 2).map(option => ({
    text: option.optionCode === 'other_text' ? '✍️ Ответить' : withEmoji(option.label),
    additionalFields: { callback_data: option.callbackData }
  })) } });
}
if (skipOptions.length === 1) {
  rows.push({ row: { buttons: [{
    text: '⏭️ Пропустить уточнения',
    additionalFields: { callback_data: skipOptions[0].callbackData }
  }] } });
}
const telegramInlineKeyboard = rows.map(row => row.row.buttons.map(button => ({
  text: button.text,callback_data: button.additionalFields.callback_data
})));
const clarificationContextValid = clarificationContext.contractVersion === 'chelsea_clarification_context_v1' &&
  Array.isArray(clarificationContext.unresolvedSlots) && clarificationContext.unresolvedSlots.length > 0;
const ready = Boolean(contextValid && chatId && preferredName && questionText && clarificationContextValid &&
  /^[0-9a-f]{16}$/.test(questionKey) && replyToken === `CS-${questionKey}` && regularOptions.length &&
  skipOptions.length === 1 && optionsUnique && normalizedOptions.length === options.length);

return [{ json: {
  ...claim,
  stateClarificationStep: claim.stateClarificationStep || claim,
  stateClarificationPromptReady: ready,
  stateClarificationPromptError: ready ? '' : 'clarification_prompt_delivery_or_context_invalid',
  stateClarificationChatId: chatId,
  stateClarificationPreferredName: preferredName,
  stateClarificationStateContext: Array.isArray(body.state) ? body.state.slice(0,10) : [],
  stateClarificationDeliveryContext: delivery,
  stateClarificationContext: clarificationContext,
  stateClarificationPromptText: questionText,
  stateClarificationInlineKeyboard: { rows },
  telegramRequestBody: { chat_id: chatId,text: questionText },
  stateClarificationTelegramRequestBody: {
    chat_id: chatId,text: questionText,reply_markup: { inline_keyboard: telegramInlineKeyboard }
  },
  stateRpcBody: {
    p_step_id: clean(claim.step_id ?? claim.stepId),
    p_lease_token: clean(claim.lease_token ?? claim.leaseToken),
    p_expected_version: Number(claim.step_version ?? claim.stepVersion),
    p_send_key: `clarification_send:${clean(claim.step_id ?? claim.stepId)}:v${Number(claim.step_version ?? claim.stepVersion)}`
  }
} }];

'use strict';

const source = $('Code | Build Clarification Telegram Request | ClarificationAsk').item.json || {};
const incoming = $input.first()?.json || {};
const body = incoming.body && typeof incoming.body === 'object' ? incoming.body : incoming;
const expectedStepId = String(source.stateRpcBody?.p_step_id || '');
const expectedSendKey = String(source.stateRpcBody?.p_send_key || '');
const baseValid = body && typeof body === 'object' && !Array.isArray(body) &&
  body.contractVersion === 'chelsea_state_clarification_send_begin_v1' &&
  String(body.stepId || '') === expectedStepId && String(body.sendKey || '') === expectedSendKey &&
  Number.isSafeInteger(Number(body.stepVersion)) &&
  typeof body.idempotentReplay === 'boolean' && typeof body.telegramSendAllowed === 'boolean';
const replay = baseValid && body.idempotentReplay === true;
const decisionConsistent = baseValid && (replay
  ? body.telegramSendAllowed === false
  : body.telegramSendAllowed === true);
const valid = baseValid && decisionConsistent;

return [{ json: {
  ...source,
  stateClarificationSendBeginResult: body,
  stateClarificationSendBeginValid: valid,
  stateClarificationTelegramSendAllowed: valid && body.telegramSendAllowed === true,
  stateClarificationPostSendUncertain: valid && replay,
  stateClarificationSendingStepVersion: valid ? Number(body.stepVersion) : Number(source.stateRpcBody?.p_expected_version),
  stateClarificationSendBeginError: valid
    ? (replay ? 'clarification_send_begin_replay_uncertain' : '')
    : String(body?.message || body?.error?.message || body?.hint || 'clarification_send_begin_invalid').slice(0, 2000)
} }];

'use strict';

const source = $('Code | Validate Clarification Send Begin | ClarificationAsk').item.json || {};
const incoming = $input.first()?.json || {};
const response = incoming.body && typeof incoming.body === 'object' ? incoming.body : incoming;
const message = response.result && typeof response.result === 'object' ? response.result : response;
const externalMessageId = String(message?.message_id ?? '').trim();
const responseChatId = String(message?.chat?.id ?? '').trim();
const expectedChatId = String(source.stateClarificationChatId || '').trim();
const exactReceipt = Boolean(externalMessageId && responseChatId && responseChatId === expectedChatId);

return [{ json: {
  ...source,
  stateClarificationTelegramReceipt: response,
  stateClarificationTelegramReceiptExact: exactReceipt,
  stateClarificationTelegramReceiptError: exactReceipt ? '' : 'clarification_telegram_receipt_invalid',
  stateRpcBody: {
    p_step_id: String(source.stateRpcBody?.p_step_id || ''),
    p_lease_token: String(source.stateRpcBody?.p_lease_token || ''),
    p_expected_version: Number(source.stateClarificationSendingStepVersion),
    p_external_message_id: externalMessageId,
    p_receipt_json: response
  }
} }];

'use strict';

const source = $('Code | Build Clarification Send Complete RPC | ClarificationAsk').item.json || {};
const incoming = $input.first()?.json || {};
const body = incoming.body && typeof incoming.body === 'object' ? incoming.body : incoming;
const valid = body && typeof body === 'object' && !Array.isArray(body) &&
  body.contractVersion === 'chelsea_state_clarification_send_complete_v1' &&
  String(body.stepId || '') === String(source.stateRpcBody?.p_step_id || '') &&
  String(body.externalMessageId || '') === String(source.stateRpcBody?.p_external_message_id || '');

return [{ json: {
  ...source,
  stateClarificationSendCompleteResult: body,
  stateClarificationSendCompleted: valid,
  stateClarificationSendCompleteError: valid
    ? ''
    : String(body?.message || body?.error?.message || body?.hint || 'clarification_send_complete_invalid').slice(0, 2000)
} }];

'use strict';

const input = $input.first()?.json || {};
let source = input;
for (const nodeName of [
  'Code | Validate Clarification Send Begin | ClarificationAsk',
  'Code | Build Clarification Telegram Request | ClarificationAsk',
  'Code | Normalize Clarification Ask Claims | ClarificationAsk',
  'Code | Normalize Clarification Answer Claims | ClarificationAnswer'
]) {
  try {
    const candidate = $(nodeName).item.json || {};
    if (candidate.step_id || candidate.stepId || candidate.stateClarificationStep) {
      source = { ...candidate, ...input };
      break;
    }
  } catch {}
}
const claim = source.stateClarificationStep || source;
const clean = value => String(value ?? '').normalize('NFKC').trim();
const postSend = source.stateClarificationPostSendUncertain === true ||
  Boolean(source.stateClarificationTelegramReceipt || source.stateClarificationTelegramReceiptError);
const expectedVersion = Number.isSafeInteger(Number(source.stateClarificationSendingStepVersion))
  ? Number(source.stateClarificationSendingStepVersion)
  : Number(claim.step_version ?? claim.stepVersion);
const errorText = [
  source.stateClarificationPromptError,
  source.stateClarificationCompositionError,
  source.stateClarificationSendBeginError,
  source.stateClarificationTelegramReceiptError,
  source.stateClarificationSendCompleteError,
  ...(Array.isArray(source.stateClarificationAnswerErrors) ? source.stateClarificationAnswerErrors : []),
  source.message,
  source.error?.message
].map(clean).filter(Boolean).join('; ').slice(0, 2000) || 'Clarification step failed.';

return [{ json: {
  ...source,
  stateRpcBody: {
    p_step_id: clean(claim.step_id ?? claim.stepId),
    p_lease_token: clean(claim.lease_token ?? claim.leaseToken),
    p_expected_version: expectedVersion,
    p_error_code: (postSend ? 'clarification_send_uncertain' : 'clarification_step_failed'),
    p_error_text: errorText,
    p_post_send_uncertain: postSend,
    p_retry_delay_minutes: 1
  }
} }];

'use strict';

const ContextualClarification = (() => {
  const clean = value => String(value ?? '').normalize('NFKC').replace(/\s+/g, ' ').trim();
  const normalized = value => clean(value).toLocaleLowerCase('ru-RU').replace(/ё/g, 'е');
  const ymdPattern = /^\d{4}-\d{2}-\d{2}$/;
  const months = ['января','февраля','марта','апреля','мая','июня','июля','августа','сентября','октября','ноября','декабря'];
  const formalPattern = /(?:^|[^\p{L}])(?:вы|вас|вам|вами|ваш|ваша|ваше|ваши|вашего|вашей|вашим|вашими|ваших)(?=$|[^\p{L}])/iu;
  const vagueReferences = new Set([
    'это','эта нагрузка','нагрузка','все','всё','ситуация','эта ситуация','это событие','произошедшее'
  ].map(normalized));
  const tokenStop = new Set([
    'это','эта','этот','эти','была','было','были','сегодня','вчера','июля','августа','сентября',
    'октября','ноября','декабря','января','февраля','марта','апреля','мая','июня','событие'
  ]);

  function localDate(timezone, localTimestamp = '') {
    const supplied = clean(localTimestamp).slice(0, 10);
    if (ymdPattern.test(supplied)) return supplied;
    const parts = new Intl.DateTimeFormat('en-US', {
      timeZone: clean(timezone) || 'UTC', year: 'numeric', month: '2-digit', day: '2-digit'
    }).formatToParts(new Date());
    const values = Object.fromEntries(parts.map(part => [part.type, part.value]));
    return `${values.year}-${values.month}-${values.day}`;
  }

  function utcDay(value) {
    if (!ymdPattern.test(value)) return Number.NaN;
    const [year,month,day] = value.split('-').map(Number);
    const time = Date.UTC(year,month - 1,day);
    const check = new Date(time);
    return check.getUTCFullYear() === year && check.getUTCMonth() === month - 1 && check.getUTCDate() === day
      ? Math.floor(time / 86400000)
      : Number.NaN;
  }

  function dateReference(sourceLocalDate, currentLocalDate) {
    const sourceDay = utcDay(sourceLocalDate);
    const currentDay = utcDay(currentLocalDate);
    if (!Number.isFinite(sourceDay) || !Number.isFinite(currentDay)) return { ready: false, error: 'local_date_invalid' };
    const delta = currentDay - sourceDay;
    if (delta < 0) return { ready: false, error: 'future_event_for_state_clarification', deltaDays: delta };
    if (delta === 0) return { ready: true, value: 'сегодня', deltaDays: 0 };
    if (delta === 1) return { ready: true, value: 'вчера', deltaDays: 1 };
    const [sourceYear,sourceMonth,sourceDate] = sourceLocalDate.split('-').map(Number);
    const currentYear = Number(currentLocalDate.slice(0,4));
    return {
      ready: true,
      value: `${sourceDate} ${months[sourceMonth - 1]}${sourceYear === currentYear ? '' : ` ${sourceYear} года`}`,
      deltaDays: delta
    };
  }

  function derive(contextValue, timezone, localTimestamp = '') {
    const context = contextValue && typeof contextValue === 'object' && !Array.isArray(contextValue)
      ? contextValue : {};
    const unresolvedSlots = Array.isArray(context.unresolvedSlots)
      ? context.unresolvedSlots.map(slot => ({
          code: clean(slot?.code), label: clean(slot?.label), questionHint: clean(slot?.questionHint)
        })).filter(slot => slot.code && slot.label && slot.questionHint)
      : [];
    const currentLocalDate = localDate(timezone, localTimestamp);
    const sourceLocalDate = clean(context.sourceLocalDate);
    const reference = dateReference(sourceLocalDate, currentLocalDate);
    const eventLabel = clean(context.eventLabel);
    const eventSummary = clean(context.eventSummary);
    const evidenceText = clean(context.evidenceText);
    const resolvedSlots = context.resolvedSlots && typeof context.resolvedSlots === 'object' && !Array.isArray(context.resolvedSlots)
      ? context.resolvedSlots : {};
    const baseReady = context.contractVersion === 'chelsea_clarification_context_v1' &&
      /^[a-z][a-z0-9_]{1,63}$/.test(clean(context.eventRuleCode)) &&
      Boolean(eventLabel && (eventSummary || evidenceText) && unresolvedSlots.length && reference.ready);
    return {
      ready: baseReady,
      error: baseReady ? '' : (reference.error || 'clarification_context_invalid'),
      contractVersion: clean(context.contractVersion),
      sourceLocalDate,
      currentLocalDate,
      dateReference: reference.value || '',
      deltaDays: reference.deltaDays,
      eventRuleCode: clean(context.eventRuleCode),
      eventLabel,
      eventSummary,
      evidenceText,
      anchorQuality: clean(context.anchorQuality),
      resolvedSlots,
      unresolvedSlots,
      unresolvedSlotCodes: unresolvedSlots.map(slot => slot.code)
    };
  }

  function tokens(value) {
    return normalized(value).match(/[\p{L}\p{N}]+/gu)?.filter(token => token.length >= 3 && !tokenStop.has(token)) || [];
  }

  function exactCodes(actual, expected) {
    if (!Array.isArray(actual) || actual.some(code => !clean(code))) return false;
    const left = actual.map(clean);
    const right = expected.map(clean);
    return left.length === new Set(left).size && left.length === right.length &&
      [...left].sort().join('\u0000') === [...right].sort().join('\u0000');
  }

  function validateResponse(parsed, contract, preferredName, maxLength = 350) {
    const text = clean(parsed?.text);
    const dateRef = clean(parsed?.dateReference);
    const eventRef = clean(parsed?.eventReference);
    const asked = Array.isArray(parsed?.askedSlotCodes) ? parsed.askedSlotCodes.map(clean) : [];
    const normalizedText = normalized(text);
    const normalizedName = normalized(preferredName);
    let nameCount = 0;
    let cursor = 0;
    while (normalizedName && (cursor = normalizedText.indexOf(normalizedName,cursor)) >= 0) {
      nameCount += 1;
      cursor += normalizedName.length;
    }
    const dateValid = dateRef === contract.dateReference && normalizedText.includes(normalized(dateRef));
    const eventVisible = Boolean(eventRef && normalizedText.includes(normalized(eventRef)));
    const grounding = normalized(`${contract.eventLabel} ${contract.eventSummary} ${contract.evidenceText}`);
    const eventTokens = tokens(eventRef);
    const eventGrounded = eventVisible && !vagueReferences.has(normalized(eventRef)) &&
      eventTokens.length > 0 && eventTokens.some(token => grounding.includes(token));
    const slotsValid = exactCodes(asked,contract.unresolvedSlotCodes);
    const checks = {
      text: Boolean(text && text.length <= maxLength),
      name: nameCount === 1,
      informal: !formalPattern.test(text),
      date: dateValid,
      event: eventGrounded,
      slots: slotsValid
    };
    const firstError = Object.entries(checks).find(([,passed]) => !passed)?.[0] || '';
    return {
      ready: Object.values(checks).every(Boolean),
      error: firstError ? `contextual_clarification_${firstError}_invalid` : '',
      text,dateReference:dateRef,eventReference:eventRef,askedSlotCodes:asked,checks
    };
  }

  return { clean, normalized, derive, validateResponse };
})();


const input = $input.first()?.json || {};
const clean = ContextualClarification.clean;
const preferredName = clean(input.stateClarificationPreferredName).replace(/[,;:]+$/u,'').trim();
const delivery = input.stateClarificationDeliveryContext && typeof input.stateClarificationDeliveryContext === 'object'
  ? input.stateClarificationDeliveryContext : {};
const timezone = clean(delivery.timezone) || 'UTC';
const contract = ContextualClarification.derive(input.stateClarificationContext,timezone);
const ready = input.stateClarificationPromptReady === true && Boolean(preferredName && contract.ready);
const request = {
  model: 'gpt-4.1-mini',
  input: [
    { role: 'system', content: [{ type: 'input_text', text: [
      'Ты — Челси. Сформулируй один живой и конкретный уточняющий вопрос для Telegram.',
      `Обращение: ${preferredName}. Назови его ровно один раз и общайся только на «ты».`,
      'В первом коротком предложении обязательно явно назови переданные dateReference и конкретное исходное событие.',
      'Во втором предложении спроси только про unresolvedSlots. resolvedSlots повторно не спрашивай.',
      'eventReference должен быть коротким буквальным фрагментом eventSummary или evidenceText и обязан присутствовать в text.',
      'Не подменяй событие другими recent events и не выдумывай подробности.',
      'Запрещены самостоятельные расплывчатые ссылки «эта нагрузка», «это», «всё», «ситуация». Сначала всегда назови событие.',
      'askedSlotCodes верни ровно для всех и только переданных unresolvedSlots.',
      'dateReference верни без изменения. Текст — 1–2 коротких предложения, не более 350 символов.',
      'Не используй «Вы», «вас», «вам», «ваш» и другие формальные формы.',
      'Верни только JSON по схеме.'
    ].join('\n') }] },
    { role: 'user', content: [{ type: 'input_text', text: JSON.stringify({
      preferredName,
      dateReference: contract.dateReference,
      sourceLocalDate: contract.sourceLocalDate,
      eventRuleCode: contract.eventRuleCode,
      eventLabel: contract.eventLabel,
      eventSummary: contract.eventSummary,
      evidenceText: contract.evidenceText,
      anchorQuality: contract.anchorQuality,
      resolvedSlots: contract.resolvedSlots,
      unresolvedSlots: contract.unresolvedSlots
    }) }] }
  ],
  temperature: 0.65,
  max_output_tokens: 220,
  text: { format: { type: 'json_schema',name: 'chelsea_contextual_clarification',strict: true,schema: {
    type: 'object',additionalProperties: false,
    required: ['text','dateReference','eventReference','askedSlotCodes'],
    properties: {
      text: { type: 'string',minLength: 12,maxLength: 350 },
      dateReference: { type: 'string',minLength: 5,maxLength: 40 },
      eventReference: { type: 'string',minLength: 3,maxLength: 160 },
      askedSlotCodes: { type: 'array',items: { type: 'string' },minItems: 1,maxItems: 12 }
    }
  } } }
};

return [{ json: {
  ...input,
  chelseaMicroPreferredName: preferredName,
  chelseaMicroRequestReady: ready,
  chelseaMicroRequestError: ready ? '' : (contract.error || 'clarification_request_invalid'),
  chelseaMicroRequest: ready ? request : {},
  chelseaMicroClarificationContract: contract,
  chelseaMicroPromptVersion: 'chelsea_micro_contextual_clarification_v2',
  chelseaMicroModel: 'gpt-4.1-mini'
} }];

'use strict';

const ContextualClarification = (() => {
  const clean = value => String(value ?? '').normalize('NFKC').replace(/\s+/g, ' ').trim();
  const normalized = value => clean(value).toLocaleLowerCase('ru-RU').replace(/ё/g, 'е');
  const ymdPattern = /^\d{4}-\d{2}-\d{2}$/;
  const months = ['января','февраля','марта','апреля','мая','июня','июля','августа','сентября','октября','ноября','декабря'];
  const formalPattern = /(?:^|[^\p{L}])(?:вы|вас|вам|вами|ваш|ваша|ваше|ваши|вашего|вашей|вашим|вашими|ваших)(?=$|[^\p{L}])/iu;
